  function date(value, withTime) { if(!value)return '—'; const d=new Date(value); if(Number.isNaN(d.getTime()))return String(value); return d.toLocaleDateString('uz-UZ',{year:'numeric',month:'2-digit',day:'2-digit',...(withTime?{hour:'2-digit',minute:'2-digit'}:{})}); }
  function age(dob) { if(!dob)return '—'; const d=new Date(dob); if(Number.isNaN(d.getTime()))return '—'; const now=new Date(); let a=now.getFullYear()-d.getFullYear(); if(now.getMonth()<d.getMonth()||(now.getMonth()===d.getMonth()&&now.getDate()<d.getDate()))a--; return a>=0?a+' yosh':'—'; }
  function name(p) { return [p&&p.last_name,p&&p.first_name,p&&p.middle_name].filter(Boolean).join(' '); }
  function initials(p) { return [p&&p.first_name,p&&p.last_name].filter(Boolean).map(n=>String(n).slice(0,1)).join('').toUpperCase()||'?'; }
  function specialist(id) { const row=S.specialists.find(s=>(s.key||s.specialist_id)===id); return row?row.label||row.name:id||'Biriktirilmagan'; }
