  function capture() { return {epoch:S.epoch,actor:S.actor,patient:S.patient?.patient_id||null,visit:S.visit?.visit_id||null}; }
  function current(c) { return !!c&&c.epoch===S.epoch&&c.actor===S.actor&&c.actor===actor()&&c.patient===(S.patient?.patient_id||null)&&c.visit===(S.visit?.visit_id||null)&&S.screen?.classList.contains('active'); }
