  function clear() { S.epoch++;stopAudio();requests.forEach(x=>x.abort());requests.clear();S.patient=null;S.visit=null;S.patients=[];S.messages=[];S.result=null;S.busy=false; }
  function notice(message, error=false) { const box=D.getElementById('upNotice'); if(!box)return;box.hidden=!message;box.textContent=message||'';box.className='up-message';box.setAttribute('role',error?'alert':'status'); }
  function resetView() { S.screen.replaceChildren(); const msg=node('div','up-message');msg.id='upNotice';msg.hidden=true;msg.setAttribute('role','status');S.screen.append(msg); }
  function xhr(path, method='GET', body, token, responseType) { return new Promise((resolve,reject)=>{const x=new XMLHttpRequest();requests.add(x);x.open(method,BASE+path,true);x.timeout=130000;x.setRequestHeader('Authorization','Bearer '+token);if(body!==undefined)x.setRequestHeader('Content-Type','application/json');if(responseType)x.responseType=responseType;x.onload=()=>{requests.delete(x);let data;if(responseType==='blob')data=x.response;else{try{data=JSON.parse(x.responseText||'{}');}catch(_){data={};}}if(x.status>=200&&x.status<300){resolve(data);return;}const message=data?.error?.message||data?.message||(typeof data?.error==='string'?data.error:null)||('So‘rov bajarilmadi ('+x.status+').');const e=Error(message);e.status=x.status;reject(e);};x.onerror=()=>{requests.delete(x);reject(Error('Server bilan aloqa uzildi. Qayta urinib ko‘ring.'));};x.onabort=()=>{requests.delete(x);reject(Error('So‘rov konteksti yopildi.'));};x.ontimeout=()=>{requests.delete(x);reject(Error('Server javobi kechikdi. Saqlangan ma’lumotni tekshirib, qayta urinib ko‘ring.'));};x.send(body===undefined?null:JSON.stringify(body));}); }
  async function api(path, method, body, responseType) { const owner=actor(),scope=capture();if(!owner||owner!==S.actor){clear();throw Error('Akkaunt o‘zgardi. Bemorlarimni qayta oching.');}const token=await W.UZMEDAuth.getAccessToken();if(!token||actor()!==owner){clear();throw Error('Sessiya tugagan. Akkauntga qayta kiring.');}try{return await xhr(path,method,body,token,responseType);}catch(e){e.upScope=scope;throw e;} }
  async function run(fn) { try{return await fn();}catch(e){if(e.upScope&&!current(e.upScope))return null;notice(e.message,true);if(e.status===401){clear();renderAccess(false);}return null;} }
  function busy(value) { S.busy=value;S.screen?.querySelectorAll('[data-up-submit]').forEach(b=>b.disabled=value||b.dataset.upBlocked==='1'); }
  function field(label, key, value, type='text', options) { const wrap=node('label','up-field');wrap.append(node('span','',label));let input;if(type==='textarea')input=node('textarea');else if(type==='select'){input=node('select');list(options).forEach(o=>{const a=node('option','',o[1]);a.value=o[0];input.append(a);});}else{input=node('input');input.type=type;}input.name=key;input.value=value??'';if(type==='date')input.max=new Date().toISOString().slice(0,10);if(type==='tel')input.autocomplete='tel';else if(/first_name|last_name/.test(key))input.autocomplete=key==='first_name'?'given-name':'family-name';else input.autocomplete='off';input.id='up-'+key;wrap.append(input);return wrap; }
