      const code=field('Telegramdagi bir martalik kod','code','','text');code.querySelector('input').required=true;code.querySelector('input').classList.add('up-link-code');code.querySelector('input').maxLength=64;
      const submit=button('Vrach akkauntini ulash',null,'up-primary','check');submit.type='submit';append(f,code,node('div','up-status-line','Kod faqat bir marta ishlatiladi. Telegram botdagi /patients buyrug‘i bilan bo‘limni ochishingiz mumkin.'),actions(submit,button('Ulanganini tekshirish',()=>run(open),'up-quiet')));p.append(f);
